const sqlDiasCase = (coluna) => {
  const chaves = Object.keys(REGRA.prazosDias).map(Number).sort((a, b) => b - a);
  const partes = chaves
    .filter((chave) => chave !== 1)
    .map((chave) => `WHEN ${coluna} ${chave === maiorFaltaRegra ? '>=' : '='} ${chave} THEN ${REGRA.prazosDias[chave]}`);
  return `CASE ${partes.join(' ')} ELSE ${REGRA.prazosDias[1]} END`;
};

const dataIso = (valor) => {
  if (!valor) {
    return null;
  }

  if (valor instanceof Date) {
    return Number.isNaN(valor.getTime()) ? null : valor.toISOString().slice(0, 10);
  }

  const texto = String(valor).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(texto) ? texto : null;
};

const somarDias = (valor, dias) => {
  const inicio = dataIso(valor);
  if (!inicio || !dias) {
    return null;
  }

  const [ano, mes, dia] = inicio.split('-').map(Number);
  const data = new Date(Date.UTC(ano, mes - 1, dia));
  if (Number.isNaN(data.getTime())) {
    return null;
  }

  data.setUTCDate(data.getUTCDate() + dias);
  return data.toISOString().slice(0, 10);
};
// ===== fim da regra =====

// Nó "separar faltas" (bloqueio às 01:00 e botão Bloquear do painel).
// No workflow Ações, o nó "Validar" informa o paciente: só as faltas dele passam,
// mesmo que a API ignore o filtro codigoPaciente da agenda.
const lerNo = (nome) => {
  try {
    return $(nome).first().json;
  } catch (erro) {
    return null;
  }
};

const inicioPeriodo = inicioCiclo();
const hoje = hojeSp();
const pacienteFiltro = Number(lerNo('Validar')?.id) || null;
const faltas = [];

for (const item of items) {
  const pagina = item.json ?? {};
  const lista = Array.isArray(pagina.lista) ? pagina.lista : [];

  for (const agendamento of lista) {
    if (agendamento.status !== 'FALTOU') {
      continue;
    }

    if (!agendamento.idPaciente || !agendamento.id) {
      continue;
    }

    if (pacienteFiltro && Number(agendamento.idPaciente) !== pacienteFiltro) {
      continue;
    }

    const dataFalta = String(agendamento.data ?? '').slice(0, 10);
    if (dataFalta < inicioPeriodo || dataFalta > hoje) {
      continue;
    }

    faltas.push({
      json: {
        ...agendamento,
        dataFalta,
        dataInicioPeriodo: inicioPeriodo,
        dataColetaReferencia: hoje
      }
    });
  }
}

faltas.sort((a, b) => {
  const porData = String(a.json.dataFalta).localeCompare(String(b.json.dataFalta));
  if (porData !== 0) {
    return porData;
  }

  return Number(a.json.id) - Number(b.json.id);
});

if (!faltas.length) {
  return [{ json: { semFaltas: true, dataInicioPeriodo: inicioPeriodo, dataFalta: hoje } }];
}

return faltas;

// ===== Regra do bloqueio por falta (fonte única: workflows/code/_regra.js) =====
// O inject.mjs copia este bloco para o início de todo nó Code que usa prazo ou ciclo.
// Para mudar a regra: edite aqui, rode `npm run inject` e publique os workflows no n8n.
const REGRA = {
  // Prazo (dias) a partir da falta vigente do ciclo. A maior chave vale para "essa ou mais".
  // Toda falta do período (ciclo) bloqueia quem está ativo no CNN enquanto o prazo corre; quem já cumpriu
  // o prazo não é bloqueado. Antes do fim do prazo, liberar só com solicitação aprovada pelo admin;
  // depois, a liberação automática (02:00) libera.
  prazosDias: { 1: 60, 2: 90, 3: 180 },
  // Início do ciclo: de outubro a dezembro, 1/10 do ano corrente; de janeiro a setembro, 1/10 do ano anterior.
  // Mudou de 1/8 para 1/10 em 2026-10-08. Mudar aqui exige mudar também a URL do nó "GET agenda do ciclo".
  cicloInicio: { mes: 10, dia: 1 },
  fuso: 'America/Sao_Paulo',
  // Só informativos (os crons ficam nos nós "Todo dia 01:00" e "Todo dia 02:00" dos workflows).
  horarioBloqueio: '01:00',
  liberacaoAutomatica: true,
  horarioLiberacao: '02:00',
};

const pad2 = (valor) => String(valor).padStart(2, '0');
const agoraSp = () => $now.setZone(REGRA.fuso);
const hojeSp = () => agoraSp().toFormat('yyyy-MM-dd');

const inicioCiclo = () => {
  const agora = agoraSp();
  const { mes, dia } = REGRA.cicloInicio;
  const jaComecou = agora.month > mes || (agora.month === mes && agora.day >= dia);
  const ano = jaComecou ? agora.year : agora.year - 1;
  return `${ano}-${pad2(mes)}-${pad2(dia)}`;
};

const maiorFaltaRegra = Math.max(...Object.keys(REGRA.prazosDias).map(Number));

const diasPorFalta = (numeroFalta) => {
  const numero = Math.min(Math.max(Number(numeroFalta) || 1, 1), maiorFaltaRegra);
  return REGRA.prazosDias[numero];
};

// Mesmo cálculo em SQL: CASE WHEN col >= 3 THEN 180 WHEN col = 2 THEN 90 ELSE 60 END.
const sqlDiasCase = (coluna) => {
  const chaves = Object.keys(REGRA.prazosDias).map(Number).sort((a, b) => b - a);
  const partes = chaves
    .filter((chave) => chave !== 1)
    .map((chave) => `WHEN ${coluna} ${chave === maiorFaltaRegra ? '>=' : '='} ${chave} THEN ${REGRA.prazosDias[chave]}`);
  return `CASE ${partes.join(' ')} ELSE ${REGRA.prazosDias[1]} END`;
};

const dataIso = (valor) => {
  if (!valor) {
    return null;
  }

  if (valor instanceof Date) {
    return Number.isNaN(valor.getTime()) ? null : valor.toISOString().slice(0, 10);
  }

  const texto = String(valor).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(texto) ? texto : null;
};

const somarDias = (valor, dias) => {
  const inicio = dataIso(valor);
  if (!inicio || !dias) {
    return null;
  }

  const [ano, mes, dia] = inicio.split('-').map(Number);
  const data = new Date(Date.UTC(ano, mes - 1, dia));
  if (Number.isNaN(data.getTime())) {
    return null;
  }

  data.setUTCDate(data.getUTCDate() + dias);
  return data.toISOString().slice(0, 10);
};
// ===== fim da regra =====

// ===== Helpers de SQL (fonte única: workflows/code/_sql.js) =====
// O SQL é montado por texto: todo valor passa por uma destas funções.
const sqlN = (valor) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const numero = Number(valor);
  return Number.isFinite(numero) ? String(Math.trunc(numero)) : 'NULL';
};

const sqlS = (valor, maxLength) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const texto = String(valor).slice(0, maxLength ?? 4000).replace(/'/g, "''");
  return `N'${texto}'`;
};

const sqlDate = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  const data = String(valor).slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    return 'NULL';
  }

  return `CONVERT(date, '${data}', 23)`;
};

const sqlTime = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  let hora = String(valor).trim();
  if (/^\d{2}:\d{2}$/.test(hora)) {
    hora = `${hora}:00`;
  }

  if (!/^\d{2}:\d{2}:\d{2}$/.test(hora)) {
    return 'NULL';
  }

  return `CONVERT(time(0), '${hora}')`;
};

const sqlBit = (valor) => {
  if (valor === null || valor === undefined) {
    return 'NULL';
  }

  return valor ? '1' : '0';
};

// Linhas devolvidas por um nó Microsoft SQL, em qualquer dos formatos que o n8n já usou.
const linhasSql = (itens) => {
  const linhas = [];

  for (const item of itens) {
    const payload = item?.json ?? {};

    if (Array.isArray(payload.recordset)) {
      linhas.push(...payload.recordset);
    } else if (Array.isArray(payload.recordsets?.[0])) {
      linhas.push(...payload.recordsets[0]);
    } else if (Object.keys(payload).length > 0 && payload.error === undefined) {
      linhas.push(payload);
    }
  }

  return linhas;
};

const erroSql = (itens) => {
  const comErro = itens.find((item) => item?.json?.error !== undefined);
  if (!comErro) {
    return null;
  }

  const erro = comErro.json.error;
  return typeof erro === 'string' ? erro : erro?.message || 'Falha no SQL Server.';
};

// Resposta de um nó HTTP com "Full Response" e "Never Error": { statusCode, body }.
// Com erro de rede e onError = continueRegularOutput, chega { error: {...} }.
const lerRespostaHttp = (json) => {
  const resposta = json ?? {};
  const erro = resposta.error;
  const statusCode = Number(resposta.statusCode ?? erro?.httpCode ?? erro?.status ?? erro?.cause?.status) || null;
  const body = resposta.body !== undefined ? resposta.body : erro ? null : resposta;
  const ok = !erro && statusCode !== null && statusCode >= 200 && statusCode < 300;
  const texto = typeof body === 'string' ? body : body ? JSON.stringify(body) : erro?.message || String(erro ?? '');
  return { ok, statusCode, body, erro: erro ? erro.message || String(erro) : null, texto: texto.slice(0, 1000) };
};

// Grava uma ação na auditoria e, se deu certo, atualiza a tabela de controle. Devolve o SQL completo.
const sqlRegistrarAcao = (acao) => {
  const situacao = acao.acao === 'LIBERACAO' ? 'LIBERADO' : 'BLOQUEADO';
  const merge = acao.sucesso
    ? `
MERGE dbo.CtlCnnControlePaciente WITH (HOLDLOCK) AS destino
USING (SELECT ${sqlN(acao.idPaciente)} AS IdPaciente) AS origem
    ON destino.IdPaciente = origem.IdPaciente
WHEN MATCHED THEN
    UPDATE SET
        NomePaciente = COALESCE(${sqlS(acao.nomePaciente, 200)}, destino.NomePaciente),
        Situacao = ${sqlS(situacao, 20)},
        IdAgendaReferencia = ${sqlN(acao.idAgenda)},
        NumeroFalta = ${sqlN(acao.numeroFalta)},
        DataInicioBloqueio = ${sqlDate(acao.dataInicioBloqueio)},
        DataFimBloqueio = ${sqlDate(acao.dataFimBloqueio)},
        UltimaAcao = ${sqlS(acao.acao, 20)},
        OrigemUltimaAcao = ${sqlS(acao.origem, 20)},
        UltimaAcaoPor = ${sqlS(acao.usuario, 100)},
        MotivoUltimaAcao = ${sqlS(acao.motivo, 500)},
        IdUltimaAcao = @IdAcao,
        UltimaAcaoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (
        IdPaciente, NomePaciente, Situacao, IdAgendaReferencia, NumeroFalta,
        DataInicioBloqueio, DataFimBloqueio, UltimaAcao, OrigemUltimaAcao,
        UltimaAcaoPor, MotivoUltimaAcao, IdUltimaAcao
    )
    VALUES (
        ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(situacao, 20)}, ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)},
        ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)},
        ${sqlS(acao.usuario, 100)}, ${sqlS(acao.motivo, 500)}, @IdAcao
    );`
    : '';

  // Solicitações de desbloqueio (dbo.CtlCnnSolicitacao), na mesma transação da auditoria.
  const idSolicitacao = sqlN(acao.idSolicitacao);
  const temSolicitacao = idSolicitacao !== 'NULL';
  const liberou = acao.sucesso && acao.acao === 'LIBERACAO';
  const solicitacoes = [];

  if (temSolicitacao && liberou) {
    // A solicitação usada nesta liberação fica LIBERADA (com "Aprovar e liberar", a decisão vai junto).
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'LIBERADA',
    LiberadoPor = ${sqlS(acao.usuario, 100)},
    LiberadoEm = SYSUTCDATETIME(),
    IdAcao = @IdAcao,
    DecididoPor = COALESCE(DecididoPor, ${sqlS(acao.aprovador, 100)}),
    DecididoEm = COALESCE(DecididoEm, CASE WHEN ${sqlS(acao.aprovador, 100)} IS NULL THEN NULL ELSE SYSUTCDATETIME() END),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND Status IN (N'PENDENTE', N'APROVADA');`);
  } else if (temSolicitacao && acao.aprovador) {
    // "Aprovar e liberar" com o CNN fora do ar: a aprovação vale; a liberação pode ser tentada de novo.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'APROVADA',
    DecididoPor = ${sqlS(acao.aprovador, 100)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND Status = N'PENDENTE';`);
  }

  if (liberou) {
    // Liberado por outro caminho (prazo cumprido): as outras solicitações abertas perdem o sentido.
    const motivoEncerramento = acao.origem === 'AUTOMATICO'
      ? 'Prazo cumprido: paciente liberado pela rotina automática.'
      : `Paciente liberado por ${acao.usuario || 'outro usuário'}.`;
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = ${sqlS(motivoEncerramento, 500)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')${temSolicitacao ? `\n  AND Id <> ${idSolicitacao}` : ''};`);
  }

  if (acao.sucesso && acao.acao === 'BLOQUEIO') {
    // Bloqueio por uma falta nova: a solicitação feita para a falta anterior não vale mais.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = N'Nova falta registrada: a solicitação era da falta anterior.',
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')
  AND IdAgendaReferencia <> ${sqlN(acao.idAgenda)};`);
  }

  return `USE INTEGRACAO;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

INSERT INTO dbo.CtlCnnAcaoPaciente (
    IdPaciente, NomePaciente, Acao, Origem, Usuario, Motivo,
    IdAgendaReferencia, NumeroFalta, DataInicioBloqueio, DataFimBloqueio,
    Antecipada, AtivoAntes, Sucesso, HttpStatus, RespostaApi, IdExecucaoN8n, IdSolicitacao
)
VALUES (
    ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)}, ${sqlS(acao.usuario || 'desconhecido', 100)}, ${sqlS(acao.motivo, 500)},
    ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)}, ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)},
    ${sqlBit(Boolean(acao.antecipada))}, ${sqlBit(acao.ativoAntes)}, ${sqlBit(Boolean(acao.sucesso))}, ${sqlN(acao.httpStatus)}, ${sqlS(acao.respostaApi, 1000)}, ${sqlS(acao.idExecucao, 50)}, ${idSolicitacao}
);

DECLARE @IdAcao BIGINT = CONVERT(BIGINT, SCOPE_IDENTITY());
${merge}
${solicitacoes.join('\n')}

COMMIT TRANSACTION;

SELECT @IdAcao AS IdAcao, CAST(${sqlBit(Boolean(acao.sucesso))} AS bit) AS Sucesso;`;
};
// Junta os itens de um nó HTTP paginado da API do CNN: cada página chega como { lista: [...] }.
// Página com erro (onError = continueRegularOutput) é ignorada.
const listaDaApi = (itens) => {
  const lista = [];

  for (const item of itens || []) {
    const pagina = item?.json ?? {};
    if (Array.isArray(pagina.lista)) {
      lista.push(...pagina.lista);
    }
  }

  return lista;
};

// Itens de um nó que pode não existir (ou não ter rodado) neste workflow: lista vazia em vez de erro.
const itensDoNo = (nome) => {
  try {
    return $(nome).all();
  } catch (erro) {
    return [];
  }
};

// MERGE em dbo.CtlCnnCadastro: linhas { tipo, id, nome, extra }. Blocos de 500 (VALUES aceita até 1000 linhas).
const sqlCadastros = (linhas) => {
  const validas = [];
  const vistos = new Set();

  for (const linha of linhas) {
    const id = Number(linha.id);
    const chave = `${linha.tipo}:${id}`;
    if (!linha.tipo || !Number.isFinite(id) || vistos.has(chave)) {
      continue;
    }
    vistos.add(chave);
    validas.push(`(${sqlS(linha.tipo, 20)}, ${sqlN(id)}, ${sqlS(linha.nome, 200)}, ${sqlS(linha.extra, 100)})`);
  }

  const blocos = [];
  for (let i = 0; i < validas.length; i += 500) {
    blocos.push(`
MERGE dbo.CtlCnnCadastro WITH (HOLDLOCK) AS destino
USING (VALUES
    ${validas.slice(i, i + 500).join(',\n    ')}
) AS origem (Tipo, Id, Nome, Extra)
    ON destino.Tipo = origem.Tipo AND destino.Id = origem.Id
WHEN MATCHED AND (ISNULL(destino.Nome, N'') <> ISNULL(origem.Nome, N'') OR ISNULL(destino.Extra, N'') <> ISNULL(origem.Extra, N'')) THEN
    UPDATE SET Nome = origem.Nome, Extra = origem.Extra, AtualizadoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (Tipo, Id, Nome, Extra) VALUES (origem.Tipo, origem.Id, origem.Nome, origem.Extra);`);
  }

  return blocos.join('\n');
};
// ===== fim dos helpers de SQL =====

// Nó "preparar insert SQL" (bloqueio às 01:00 e botão Bloquear do painel).
// Monta uma query só para o nó "gravar faltas" (o nó Microsoft SQL roda só a query do 1º item), numa transação:
//   1. cadastros (nomes de tipo de consulta, profissional, rótulo, local, especialidade): MERGE em CtlCnnCadastro;
//   2. todas as faltas lidas vão para a tabela temporária #faltas (INSERT de até 1000 linhas por vez);
//   3. falta já gravada: UPDATE dos dados da agenda (tipo de consulta, rótulo, profissional, local, horário),
//      que podem mudar no CNN; dados do paciente só completam o que estiver vazio;
//   4. falta nova: INSERT (NumeroFalta provisório 0, acertado no passo 6);
//   5. procedimentos das faltas lidas: apaga e grava de novo (CtlCnnFaltaProcedimento);
//   6. renumera NumeroFalta por data no ciclo, para os pacientes lidos.
// Profissional: a agenda traz idPessoaExecutor, que é o "idpessoa" da lista /executor-agenda/lista
// (não o "id" do executor; por isso o GET /executor-agenda/{id} antigo nunca achava ninguém).
const inicioPeriodo = inicioCiclo();
const faltas = $('separar faltas').all().filter((item) => !item.json.semFaltas).map((item) => item.json ?? {});

if (!faltas.length) {
  return [];
}

// Pacientes por id (o GET roda uma vez por paciente, no nó "pacientes únicos").
const pacientes = new Map();
for (const item of itensDoNo('GET paciente por id')) {
  const paciente = item.json ?? {};
  const id = Number(paciente.id);
  if (Number.isFinite(id) && !paciente.error && !paciente.message) {
    pacientes.set(id, paciente);
  }
}

// Listas de cadastro. Nó que não existe neste workflow (Ações só lê executores) ou que falhou: lista vazia.
const executores = listaDaApi(itensDoNo('GET executores'));
const executorPorPessoa = new Map();
for (const executor of executores) {
  const idPessoa = Number(executor.idpessoa);
  if (Number.isFinite(idPessoa)) {
    executorPorPessoa.set(idPessoa, executor);
  }
}

const cadastros = [
  ...listaDaApi(itensDoNo('GET tipos de consulta')).map((t) => ({ tipo: 'TIPO_CONSULTA', id: t.id, nome: t.nome, extra: t.reconsulta === true ? 'RECONSULTA' : null })),
  ...executores.map((e) => ({ tipo: 'EXECUTOR', id: e.idpessoa, nome: e.nome, extra: e.tipoExecutor || null })),
  ...listaDaApi(itensDoNo('GET rótulos')).map((r) => ({ tipo: 'ROTULO', id: r.id, nome: r.nome, extra: r.corRotulo || null })),
  ...listaDaApi(itensDoNo('GET locais')).map((l) => ({ tipo: 'LOCAL_AGENDA', id: l.id, nome: l.nome, extra: null })),
  ...listaDaApi(itensDoNo('GET especialidades')).map((e) => ({ tipo: 'ESPECIALIDADE', id: e.id, nome: e.nome, extra: null })),
];

// Procedimentos de uma falta, sem repetir o mesmo tipo (soma a quantidade).
const procedimentosDe = (falta) => {
  const porTipo = new Map();
  for (const proc of Array.isArray(falta.procedimentos) ? falta.procedimentos : []) {
    const idTipo = Number(proc?.idTipoProcedimento);
    if (!Number.isFinite(idTipo)) {
      continue;
    }
    const atual = porTipo.get(idTipo);
    const quantidade = Number(proc.quantidade) || 1;
    if (atual) {
      atual.quantidade += quantidade;
    } else {
      porTipo.set(idTipo, { idTipo, nome: proc.nome, idEspecialidade: proc.idEspecialidade, quantidade });
    }
  }
  return [...porTipo.values()];
};

// A mesma falta pode aparecer duas vezes se a agenda mudar entre uma página e outra: fica a última.
const porAgenda = new Map();
for (const falta of faltas) {
  if (sqlN(falta.id) !== 'NULL') {
    porAgenda.set(Number(falta.id), falta);
  }
}

const linhaFalta = (falta) => {
  const paciente = pacientes.get(Number(falta.idPaciente)) || null;
  const contato = paciente?.contato ?? {};
  const executor = executorPorPessoa.get(Number(falta.idPessoaExecutor)) || null;

  return `(${[
    sqlN(falta.id),
    sqlN(falta.idPaciente),
    sqlS(paciente ? paciente.nome : null, 200),
    sqlS(paciente ? paciente.cpfcnpj : null, 20),
    sqlS(contato.email || falta.emailPaciente, 200),
    sqlS(contato.telefoneCelular || falta.telefoneCelularPaciente, 30),
    sqlDate(falta.dataFalta || falta.data),
    sqlTime(falta.horaInicio),
    sqlTime(falta.horaFim),
    sqlS(falta.status, 50),
    sqlN(falta.idPessoaExecutor),
    sqlN(executor ? executor.id : null),
    sqlS(executor ? executor.nome : null, 200),
    sqlS(executor ? executor.tipoExecutor : null, 50),
    sqlN(falta.idLocalAgenda),
    sqlN(falta.idTipoConsulta),
    sqlN(falta.idRotulo),
    sqlS(falta.observacoes, 500),
  ].join(', ')})`;
};

const emBlocos = (linhas, tamanho, montar) => {
  const blocos = [];
  for (let i = 0; i < linhas.length; i += tamanho) {
    blocos.push(montar(linhas.slice(i, i + tamanho)));
  }
  return blocos.join('\n');
};

const linhasFaltas = [...porAgenda.values()].map(linhaFalta);
const linhasProcedimentos = [...porAgenda.values()].flatMap((falta) =>
  procedimentosDe(falta).map((proc) =>
    `(${sqlN(falta.id)}, ${sqlN(proc.idTipo)}, ${sqlS(proc.nome, 200)}, ${sqlN(proc.idEspecialidade)}, ${sqlN(proc.quantidade)})`
  )
);

const idsPacientes = [...new Set(faltas.map((falta) => Number(falta.idPaciente)).filter((id) => Number.isFinite(id)))];

const query = `USE INTEGRACAO;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
${sqlCadastros(cadastros)}

IF OBJECT_ID(N'tempdb..#faltas') IS NOT NULL
    DROP TABLE #faltas;

CREATE TABLE #faltas (
    IdAgenda BIGINT NOT NULL PRIMARY KEY,
    IdPaciente BIGINT NOT NULL,
    NomePaciente NVARCHAR(200) NULL,
    CpfCnpj NVARCHAR(20) NULL,
    EmailPaciente NVARCHAR(200) NULL,
    TelefonePaciente NVARCHAR(30) NULL,
    DataFalta DATE NOT NULL,
    HoraInicio TIME(0) NULL,
    HoraFim TIME(0) NULL,
    StatusAgenda NVARCHAR(50) NOT NULL,
    IdPessoaExecutor BIGINT NULL,
    IdExecutorAgenda BIGINT NULL,
    NomeExecutor NVARCHAR(200) NULL,
    TipoExecutor NVARCHAR(50) NULL,
    IdLocalAgenda BIGINT NULL,
    IdTipoConsulta BIGINT NULL,
    IdRotulo BIGINT NULL,
    Observacoes NVARCHAR(500) NULL
);

${emBlocos(linhasFaltas, 1000, (bloco) => `INSERT INTO #faltas VALUES
    ${bloco.join(',\n    ')};`)}

UPDATE destino
SET
    HoraInicio = origem.HoraInicio,
    HoraFim = origem.HoraFim,
    IdPessoaExecutor = origem.IdPessoaExecutor,
    IdExecutorAgenda = COALESCE(origem.IdExecutorAgenda, destino.IdExecutorAgenda),
    NomeExecutor = COALESCE(origem.NomeExecutor, destino.NomeExecutor),
    TipoExecutor = COALESCE(origem.TipoExecutor, destino.TipoExecutor),
    IdLocalAgenda = origem.IdLocalAgenda,
    IdTipoConsulta = origem.IdTipoConsulta,
    IdRotulo = origem.IdRotulo,
    Observacoes = origem.Observacoes,
    NomePaciente = COALESCE(destino.NomePaciente, origem.NomePaciente),
    CpfCnpj = COALESCE(destino.CpfCnpj, origem.CpfCnpj),
    EmailPaciente = COALESCE(destino.EmailPaciente, origem.EmailPaciente),
    TelefonePaciente = COALESCE(destino.TelefonePaciente, origem.TelefonePaciente)
FROM dbo.CtlCnnFaltaPaciente AS destino
INNER JOIN #faltas AS origem
    ON origem.IdAgenda = destino.IdAgenda;

INSERT INTO dbo.CtlCnnFaltaPaciente (
    IdAgenda, IdPaciente, NomePaciente, CpfCnpj, EmailPaciente, TelefonePaciente,
    DataFalta, HoraInicio, HoraFim, StatusAgenda,
    IdPessoaExecutor, IdExecutorAgenda, NomeExecutor, TipoExecutor,
    IdLocalAgenda, IdTipoConsulta, IdRotulo, Observacoes, NumeroFalta
)
SELECT
    origem.IdAgenda, origem.IdPaciente, origem.NomePaciente, origem.CpfCnpj, origem.EmailPaciente, origem.TelefonePaciente,
    origem.DataFalta, origem.HoraInicio, origem.HoraFim, origem.StatusAgenda,
    origem.IdPessoaExecutor, origem.IdExecutorAgenda, origem.NomeExecutor, origem.TipoExecutor,
    origem.IdLocalAgenda, origem.IdTipoConsulta, origem.IdRotulo, origem.Observacoes, 0
FROM #faltas AS origem
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.CtlCnnFaltaPaciente f WHERE f.IdAgenda = origem.IdAgenda
);

DECLARE @novas INT = @@ROWCOUNT;

DELETE p
FROM dbo.CtlCnnFaltaProcedimento AS p
INNER JOIN #faltas AS origem
    ON origem.IdAgenda = p.IdAgenda;

${emBlocos(linhasProcedimentos, 1000, (bloco) => `INSERT INTO dbo.CtlCnnFaltaProcedimento (IdAgenda, IdTipoProcedimento, NomeProcedimento, IdEspecialidade, Quantidade)
VALUES
    ${bloco.join(',\n    ')};`)}

-- Reordena NumeroFalta por data dentro do ciclo (uma falta antiga pode chegar depois de uma nova; as novas entram com 0).
;WITH Numeracao AS (
    SELECT
        Id,
        ROW_NUMBER() OVER (
            PARTITION BY IdPaciente
            ORDER BY DataFalta, IdAgenda
        ) AS NumeroCalculado
    FROM dbo.CtlCnnFaltaPaciente
    WHERE IdPaciente IN (SELECT DISTINCT IdPaciente FROM #faltas)
      AND DataFalta >= CONVERT(date, '${inicioPeriodo}', 23)
)
UPDATE destino
SET NumeroFalta = origem.NumeroCalculado
FROM dbo.CtlCnnFaltaPaciente AS destino
INNER JOIN Numeracao AS origem
    ON origem.Id = destino.Id
WHERE destino.NumeroFalta <> origem.NumeroCalculado;

DROP TABLE #faltas;

COMMIT TRANSACTION;

SELECT CAST(${porAgenda.size} AS int) AS faltasLidas, @novas AS faltasNovas, CAST(${cadastros.length} AS int) AS cadastrosLidos;`;

return [{
  json: {
    query,
    quantidadeFaltas: porAgenda.size,
    quantidadeCadastros: cadastros.length,
    dataInicioPeriodo: inicioPeriodo,
    idsPacientes,
    listaIds: idsPacientes.join(', ')
  }
}];

// ===== Regra do bloqueio por falta (fonte única: workflows/code/_regra.js) =====
// O inject.mjs copia este bloco para o início de todo nó Code que usa prazo ou ciclo.
// Para mudar a regra: edite aqui, rode `npm run inject` e publique os workflows no n8n.
const REGRA = {
  // Prazo (dias) a partir da falta vigente do ciclo. A maior chave vale para "essa ou mais".
  // Toda falta do período (ciclo) bloqueia quem está ativo no CNN enquanto o prazo corre; quem já cumpriu
  // o prazo não é bloqueado. Antes do fim do prazo, liberar só com solicitação aprovada pelo admin;
  // depois, a liberação automática (02:00) libera.
  prazosDias: { 1: 60, 2: 90, 3: 180 },
  // Início do ciclo: de outubro a dezembro, 1/10 do ano corrente; de janeiro a setembro, 1/10 do ano anterior.
  // Mudou de 1/8 para 1/10 em 2026-10-08. Mudar aqui exige mudar também a URL do nó "GET agenda do ciclo".
  cicloInicio: { mes: 10, dia: 1 },
  fuso: 'America/Sao_Paulo',
  // Só informativos (os crons ficam nos nós "Todo dia 01:00" e "Todo dia 02:00" dos workflows).
  horarioBloqueio: '01:00',
  liberacaoAutomatica: true,
  horarioLiberacao: '02:00',
};

const pad2 = (valor) => String(valor).padStart(2, '0');
const agoraSp = () => $now.setZone(REGRA.fuso);
const hojeSp = () => agoraSp().toFormat('yyyy-MM-dd');

const inicioCiclo = () => {
  const agora = agoraSp();
  const { mes, dia } = REGRA.cicloInicio;
  const jaComecou = agora.month > mes || (agora.month === mes && agora.day >= dia);
  const ano = jaComecou ? agora.year : agora.year - 1;
  return `${ano}-${pad2(mes)}-${pad2(dia)}`;
};

const maiorFaltaRegra = Math.max(...Object.keys(REGRA.prazosDias).map(Number));

const diasPorFalta = (numeroFalta) => {
  const numero = Math.min(Math.max(Number(numeroFalta) || 1, 1), maiorFaltaRegra);
  return REGRA.prazosDias[numero];
};

// Mesmo cálculo em SQL: CASE WHEN col >= 3 THEN 180 WHEN col = 2 THEN 90 ELSE 60 END.
const sqlDiasCase = (coluna) => {
  const chaves = Object.keys(REGRA.prazosDias).map(Number).sort((a, b) => b - a);
  const partes = chaves
    .filter((chave) => chave !== 1)
    .map((chave) => `WHEN ${coluna} ${chave === maiorFaltaRegra ? '>=' : '='} ${chave} THEN ${REGRA.prazosDias[chave]}`);
  return `CASE ${partes.join(' ')} ELSE ${REGRA.prazosDias[1]} END`;
};

const dataIso = (valor) => {
  if (!valor) {
    return null;
  }

  if (valor instanceof Date) {
    return Number.isNaN(valor.getTime()) ? null : valor.toISOString().slice(0, 10);
  }

  const texto = String(valor).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(texto) ? texto : null;
};

const somarDias = (valor, dias) => {
  const inicio = dataIso(valor);
  if (!inicio || !dias) {
    return null;
  }

  const [ano, mes, dia] = inicio.split('-').map(Number);
  const data = new Date(Date.UTC(ano, mes - 1, dia));
  if (Number.isNaN(data.getTime())) {
    return null;
  }

  data.setUTCDate(data.getUTCDate() + dias);
  return data.toISOString().slice(0, 10);
};
// ===== fim da regra =====

// ===== Helpers de SQL (fonte única: workflows/code/_sql.js) =====
// O SQL é montado por texto: todo valor passa por uma destas funções.
const sqlN = (valor) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const numero = Number(valor);
  return Number.isFinite(numero) ? String(Math.trunc(numero)) : 'NULL';
};

const sqlS = (valor, maxLength) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const texto = String(valor).slice(0, maxLength ?? 4000).replace(/'/g, "''");
  return `N'${texto}'`;
};

const sqlDate = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  const data = String(valor).slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    return 'NULL';
  }

  return `CONVERT(date, '${data}', 23)`;
};

const sqlTime = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  let hora = String(valor).trim();
  if (/^\d{2}:\d{2}$/.test(hora)) {
    hora = `${hora}:00`;
  }

  if (!/^\d{2}:\d{2}:\d{2}$/.test(hora)) {
    return 'NULL';
  }

  return `CONVERT(time(0), '${hora}')`;
};

const sqlBit = (valor) => {
  if (valor === null || valor === undefined) {
    return 'NULL';
  }

  return valor ? '1' : '0';
};

// Linhas devolvidas por um nó Microsoft SQL, em qualquer dos formatos que o n8n já usou.
const linhasSql = (itens) => {
  const linhas = [];

  for (const item of itens) {
    const payload = item?.json ?? {};

    if (Array.isArray(payload.recordset)) {
      linhas.push(...payload.recordset);
    } else if (Array.isArray(payload.recordsets?.[0])) {
      linhas.push(...payload.recordsets[0]);
    } else if (Object.keys(payload).length > 0 && payload.error === undefined) {
      linhas.push(payload);
    }
  }

  return linhas;
};

const erroSql = (itens) => {
  const comErro = itens.find((item) => item?.json?.error !== undefined);
  if (!comErro) {
    return null;
  }

  const erro = comErro.json.error;
  return typeof erro === 'string' ? erro : erro?.message || 'Falha no SQL Server.';
};

// Resposta de um nó HTTP com "Full Response" e "Never Error": { statusCode, body }.
// Com erro de rede e onError = continueRegularOutput, chega { error: {...} }.
const lerRespostaHttp = (json) => {
  const resposta = json ?? {};
  const erro = resposta.error;
  const statusCode = Number(resposta.statusCode ?? erro?.httpCode ?? erro?.status ?? erro?.cause?.status) || null;
  const body = resposta.body !== undefined ? resposta.body : erro ? null : resposta;
  const ok = !erro && statusCode !== null && statusCode >= 200 && statusCode < 300;
  const texto = typeof body === 'string' ? body : body ? JSON.stringify(body) : erro?.message || String(erro ?? '');
  return { ok, statusCode, body, erro: erro ? erro.message || String(erro) : null, texto: texto.slice(0, 1000) };
};

// Grava uma ação na auditoria e, se deu certo, atualiza a tabela de controle. Devolve o SQL completo.
const sqlRegistrarAcao = (acao) => {
  const situacao = acao.acao === 'LIBERACAO' ? 'LIBERADO' : 'BLOQUEADO';
  const merge = acao.sucesso
    ? `
MERGE dbo.CtlCnnControlePaciente WITH (HOLDLOCK) AS destino
USING (SELECT ${sqlN(acao.idPaciente)} AS IdPaciente) AS origem
    ON destino.IdPaciente = origem.IdPaciente
WHEN MATCHED THEN
    UPDATE SET
        NomePaciente = COALESCE(${sqlS(acao.nomePaciente, 200)}, destino.NomePaciente),
        Situacao = ${sqlS(situacao, 20)},
        IdAgendaReferencia = ${sqlN(acao.idAgenda)},
        NumeroFalta = ${sqlN(acao.numeroFalta)},
        DataInicioBloqueio = ${sqlDate(acao.dataInicioBloqueio)},
        DataFimBloqueio = ${sqlDate(acao.dataFimBloqueio)},
        UltimaAcao = ${sqlS(acao.acao, 20)},
        OrigemUltimaAcao = ${sqlS(acao.origem, 20)},
        UltimaAcaoPor = ${sqlS(acao.usuario, 100)},
        MotivoUltimaAcao = ${sqlS(acao.motivo, 500)},
        IdUltimaAcao = @IdAcao,
        UltimaAcaoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (
        IdPaciente, NomePaciente, Situacao, IdAgendaReferencia, NumeroFalta,
        DataInicioBloqueio, DataFimBloqueio, UltimaAcao, OrigemUltimaAcao,
        UltimaAcaoPor, MotivoUltimaAcao, IdUltimaAcao
    )
    VALUES (
        ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(situacao, 20)}, ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)},
        ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)},
        ${sqlS(acao.usuario, 100)}, ${sqlS(acao.motivo, 500)}, @IdAcao
    );`
    : '';

  // Solicitações de desbloqueio (dbo.CtlCnnSolicitacao), na mesma transação da auditoria.
  const idSolicitacao = sqlN(acao.idSolicitacao);
  const temSolicitacao = idSolicitacao !== 'NULL';
  const liberou = acao.sucesso && acao.acao === 'LIBERACAO';
  const solicitacoes = [];

  if (temSolicitacao && liberou) {
    // A solicitação usada nesta liberação fica LIBERADA (com "Aprovar e liberar", a decisão vai junto).
